solutions.naive:
class Solution:
    def numDecodings(self, s: str) -> int:
        def dfs(i: int) -> int:
            if i == len(s):
                return 1
            if s[i] == "0":
                return 0
            total = dfs(i + 1)
            if i + 1 < len(s) and 10 <= int(s[i:i + 2]) <= 26:
                total += dfs(i + 2)
            return total

        return dfs(0)

