class Solution:
    def numDecodings(self, s: str) -> int:
        next1, next2 = 1, 0  # dp[i+1], dp[i+2]
        for i in range(len(s) - 1, -1, -1):
            current = 0
            if s[i] != "0":
                current = next1
                if i + 1 < len(s) and 10 <= int(s[i:i + 2]) <= 26:
                    current += next2
            next1, next2 = current, next1
        return next1

